package cpamp

import "encoding/json"

func encode(v any) json.RawMessage { b, _ := json.Marshal(v); return b }

func withEventTiming(o Observation, e Event) Observation {
	if e.HeaderTime > 0 {
		o.TimeLow, o.TimeHigh, o.TimeSource = max(e.Started, e.HeaderTime-quotaClockMarginMS), min(e.Completed, e.HeaderTime+1000+quotaClockMarginMS), "provider_date_with_request_bounds"
		if e.HeaderTime < e.Started-5000 || e.HeaderTime > e.Completed+5000 {
			o.TimeSource = "clock_conflict"
		}
	} else if e.Completed >= e.Started && e.Started > 0 {
		o.TimeLow, o.TimeHigh, o.TimeSource = e.Started, e.Completed, "request_interval"
	} else {
		o.TimeSource = "unknown"
	}
	return o
}
